// Auto-generated by CAF
// T4.5: AI-Assisted Auto-Repair Pipeline
// Orchestrates DOM drift detection, optimization, and repair

import fs from 'fs';
import path from 'path';
import { loadDriftState, generatePredictions } from './dom-drift-predictor';
import { analyzeSelector, SelectorAnalysis } from './locator-optimizer';
import { attemptRepair, RepairResult } from './selector-repair';
import { loadLifecycleStore, getRetiredSelectors } from './selector-lifecycle';

// ─────────────────────────────────────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────────────────────────────────────

const PIPELINE_REPORT_FILE = 'auto-repair-report.json';
const ANALYSIS_DIR = 'migration-analysis';
const SNAPSHOTS_DIR = '.caf-dom-snapshots';

// Thresholds
const AUTO_REPAIR_CONFIDENCE_THRESHOLD = 90;  // Auto-apply repairs above this

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface PipelineSelector {
  selector: string;
  score: number;
  source: string;          // analysis file path
}

interface PipelineStage {
  name: string;
  status: 'pass' | 'warn' | 'fail';
  findings: number;
  details: string[];
}

interface PipelineAction {
  selector: string;
  action: 'repair' | 'optimize' | 'retire' | 'monitor';
  reason: string;
  automaticApplied: boolean;
  suggestion?: string;
}

interface PipelineReport {
  timestamp: string;
  stages: PipelineStage[];
  actions: PipelineAction[];
  summary: {
    totalSelectors: number;
    atRisk: number;
    autoApplied: number;
    optimizations: number;
    retirements: number;
    monitored: number;
  };
  exitCode: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Pipeline Stages
// ─────────────────────────────────────────────────────────────────────────────

function collectSelectors(): PipelineSelector[] {
  const selectors: PipelineSelector[] = [];

  function scanDir(dir: string) {
    if (!fs.existsSync(dir)) return;

    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        scanDir(fullPath);
      } else if (entry.name.endsWith('.analysis.json')) {
        try {
          const content = JSON.parse(fs.readFileSync(fullPath, 'utf-8'));

          for (const sel of content.selectors || []) {
            selectors.push({
              selector: sel.primary,
              score: sel.score,
              source: fullPath,
            });
          }
        } catch {
          // Skip invalid files
        }
      }
    }
  }

  scanDir(ANALYSIS_DIR);
  return selectors;
}

function runDriftDetection(): PipelineStage {
  const stage: PipelineStage = {
    name: 'Drift Detection',
    status: 'pass',
    findings: 0,
    details: [],
  };

  try {
    const driftState = loadDriftState();
    const predictions = generatePredictions(driftState);

    const critical = predictions.filter(p => p.riskLevel === 'critical');
    const high = predictions.filter(p => p.riskLevel === 'high');

    stage.findings = critical.length + high.length;

    if (critical.length > 0) {
      stage.status = 'fail';
      stage.details.push(`${critical.length} CRITICAL risk selectors`);

      for (const p of critical.slice(0, 3)) {
        stage.details.push(`  - ${p.selector}: ${p.prediction}`);
      }
    }

    if (high.length > 0) {
      stage.status = stage.status === 'fail' ? 'fail' : 'warn';
      stage.details.push(`${high.length} HIGH risk selectors`);
    }

    if (stage.findings === 0) {
      stage.details.push('No at-risk selectors detected');
    }
  } catch (error) {
    stage.status = 'warn';
    stage.details.push('Drift state not available (first run?)');
  }

  return stage;
}

function runLifecycleCheck(): PipelineStage {
  const stage: PipelineStage = {
    name: 'Lifecycle Check',
    status: 'pass',
    findings: 0,
    details: [],
  };

  try {
    const store = loadLifecycleStore();
    const retired = getRetiredSelectors(store);

    const watch = Object.values(store.selectors).filter(s => s.state === 'watch');

    stage.findings = retired.length + watch.length;

    if (retired.length > 0) {
      stage.status = 'warn';
      stage.details.push(`${retired.length} retired selectors (need replacement)`);

      for (const r of retired.slice(0, 3)) {
        stage.details.push(`  - ${r}`);
      }
    }

    if (watch.length > 0) {
      stage.details.push(`${watch.length} selectors on watch list`);
    }

    if (stage.findings === 0) {
      stage.details.push('All selectors in active state');
    }
  } catch {
    stage.details.push('Lifecycle state not available');
  }

  return stage;
}

function runOptimizationScan(selectors: PipelineSelector[]): {
  stage: PipelineStage;
  analyses: Map<string, SelectorAnalysis>;
} {
  const stage: PipelineStage = {
    name: 'Optimization Scan',
    status: 'pass',
    findings: 0,
    details: [],
  };

  const analyses = new Map<string, SelectorAnalysis>();
  let highPriority = 0;
  let mediumPriority = 0;

  for (const sel of selectors) {
    const analysis = analyzeSelector(sel.selector, sel.score);
    analyses.set(sel.selector, analysis);

    const highSuggestions = analysis.suggestions.filter(s => s.priority === 'high');
    const mediumSuggestions = analysis.suggestions.filter(s => s.priority === 'medium');

    highPriority += highSuggestions.length;
    mediumPriority += mediumSuggestions.length;
  }

  stage.findings = highPriority + mediumPriority;

  if (highPriority > 0) {
    stage.status = 'warn';
    stage.details.push(`${highPriority} high-priority optimization suggestions`);
  }

  if (mediumPriority > 0) {
    stage.details.push(`${mediumPriority} medium-priority suggestions`);
  }

  if (stage.findings === 0) {
    stage.details.push('All selectors optimally configured');
  }

  return { stage, analyses };
}

function runRepairAttempts(
  atRiskSelectors: string[],
  htmlContent: string | null
): { stage: PipelineStage; results: Map<string, RepairResult> } {
  const stage: PipelineStage = {
    name: 'Auto-Repair Attempts',
    status: 'pass',
    findings: 0,
    details: [],
  };

  const results = new Map<string, RepairResult>();

  if (!htmlContent) {
    stage.details.push('No DOM snapshot available for repair');
    return { stage, results };
  }

  if (atRiskSelectors.length === 0) {
    stage.details.push('No selectors requiring repair');
    return { stage, results };
  }

  let repaired = 0;
  let multipleOptions = 0;
  let failed = 0;

  for (const selector of atRiskSelectors) {
    try {
      const result = attemptRepair(selector, htmlContent);
      results.set(selector, result);

      switch (result.status) {
        case 'repaired':
          repaired++;
          break;
        case 'multiple-options':
          multipleOptions++;
          break;
        case 'failed':
          failed++;
          break;
      }
    } catch {
      failed++;
    }
  }

  stage.findings = atRiskSelectors.length;

  if (repaired > 0) {
    stage.details.push(`${repaired} selectors auto-repaired`);
  }

  if (multipleOptions > 0) {
    stage.status = 'warn';
    stage.details.push(`${multipleOptions} need manual review`);
  }

  if (failed > 0) {
    stage.status = failed === atRiskSelectors.length ? 'fail' : 'warn';
    stage.details.push(`${failed} repair attempts failed`);
  }

  return { stage, results };
}

// ─────────────────────────────────────────────────────────────────────────────
// Pipeline Orchestration
// ─────────────────────────────────────────────────────────────────────────────

function runPipeline(options: {
  autoApply: boolean;
  snapshotPath?: string;
}): PipelineReport {
  const stages: PipelineStage[] = [];
  const actions: PipelineAction[] = [];

  // Collect all selectors
  const selectors = collectSelectors();

  // Stage 1: Drift Detection
  const driftStage = runDriftDetection();
  stages.push(driftStage);

  // Stage 2: Lifecycle Check
  const lifecycleStage = runLifecycleCheck();
  stages.push(lifecycleStage);

  // Stage 3: Optimization Scan
  const { stage: optimizationStage, analyses } = runOptimizationScan(selectors);
  stages.push(optimizationStage);

  // Identify at-risk selectors for repair
  const atRiskSelectors: string[] = [];

  // From drift predictions
  try {
    const driftState = loadDriftState();
    const predictions = generatePredictions(driftState);

    for (const p of predictions) {
      if (p.riskLevel === 'critical' || p.riskLevel === 'high') {
        if (!atRiskSelectors.includes(p.selector)) {
          atRiskSelectors.push(p.selector);
        }
      }
    }
  } catch {
    // Continue without drift data
  }

  // From lifecycle (retired selectors)
  try {
    const store = loadLifecycleStore();
    const retired = getRetiredSelectors(store);

    for (const r of retired) {
      if (!atRiskSelectors.includes(r)) {
        atRiskSelectors.push(r);
      }
    }
  } catch {
    // Continue without lifecycle data
  }

  // Load DOM snapshot for repairs
  let htmlContent: string | null = null;

  if (options.snapshotPath && fs.existsSync(options.snapshotPath)) {
    htmlContent = fs.readFileSync(options.snapshotPath, 'utf-8');
  } else if (fs.existsSync(SNAPSHOTS_DIR)) {
    const files = fs.readdirSync(SNAPSHOTS_DIR)
      .filter(f => f.endsWith('.html'))
      .sort()
      .reverse();

    if (files.length > 0) {
      htmlContent = fs.readFileSync(path.join(SNAPSHOTS_DIR, files[0]), 'utf-8');
    }
  }

  // Stage 4: Auto-Repair Attempts
  const { stage: repairStage, results: repairResults } = runRepairAttempts(
    atRiskSelectors,
    htmlContent
  );
  stages.push(repairStage);

  // Generate actions based on findings
  let autoAppliedCount = 0;
  let optimizationsCount = 0;
  let retirementsCount = 0;
  let monitoredCount = 0;

  // Process repair results
  for (const [selector, result] of repairResults.entries()) {
    if (result.status === 'repaired' && result.selectedRepair) {
      const autoApplied = options.autoApply &&
        result.selectedRepair.confidence >= AUTO_REPAIR_CONFIDENCE_THRESHOLD;

      actions.push({
        selector,
        action: 'repair',
        reason: `Found replacement: ${result.selectedRepair.selector}`,
        automaticApplied: autoApplied,
        suggestion: result.selectedRepair.selector,
      });

      if (autoApplied) {
        autoAppliedCount++;
      }
    } else if (result.status === 'failed') {
      actions.push({
        selector,
        action: 'retire',
        reason: result.reason || 'No repair candidates found',
        automaticApplied: false,
      });
      retirementsCount++;
    } else if (result.status === 'multiple-options') {
      actions.push({
        selector,
        action: 'monitor',
        reason: 'Multiple repair options - manual review needed',
        automaticApplied: false,
        suggestion: result.candidates[0]?.selector,
      });
      monitoredCount++;
    }
  }

  // Process optimization suggestions
  for (const [selector, analysis] of analyses.entries()) {
    if (repairResults.has(selector)) continue;  // Already handled

    const highPriority = analysis.suggestions.filter(s => s.priority === 'high');

    if (highPriority.length > 0) {
      actions.push({
        selector,
        action: 'optimize',
        reason: highPriority[0].suggestion,
        automaticApplied: false,
      });
      optimizationsCount++;
    }
  }

  // Calculate exit code
  let exitCode = 0;

  for (const stage of stages) {
    if (stage.status === 'fail') {
      exitCode = 1;
      break;
    }
  }

  return {
    timestamp: new Date().toISOString(),
    stages,
    actions,
    summary: {
      totalSelectors: selectors.length,
      atRisk: atRiskSelectors.length,
      autoApplied: autoAppliedCount,
      optimizations: optimizationsCount,
      retirements: retirementsCount,
      monitored: monitoredCount,
    },
    exitCode,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// CLI Entry Point
// ─────────────────────────────────────────────────────────────────────────────

function main() {
  const args = process.argv.slice(2);

  const autoApply = args.includes('--auto');
  const ciMode = args.includes('--ci');
  const verbose = args.includes('--verbose');

  let snapshotPath: string | undefined;
  const snapshotIdx = args.indexOf('--snapshot');
  if (snapshotIdx !== -1 && args[snapshotIdx + 1]) {
    snapshotPath = args[snapshotIdx + 1];
  }

  console.log('═══════════════════════════════════════════════════════════════');
  console.log('  T4.5: AI-Assisted Auto-Repair Pipeline');
  console.log('═══════════════════════════════════════════════════════════════');

  const report = runPipeline({ autoApply, snapshotPath });

  // Display stages
  console.log('\nPipeline Stages:');

  for (const stage of report.stages) {
    const icon = stage.status === 'pass' ? '✓' :
                 stage.status === 'warn' ? '⚠' : '✗';
    const statusDisplay = stage.status.toUpperCase().padEnd(4);

    console.log(`\n${icon} ${stage.name} [${statusDisplay}]`);

    for (const detail of stage.details) {
      console.log(`  ${detail}`);
    }
  }

  // Display actions
  if (report.actions.length > 0) {
    console.log('\n───────────────────────────────────────────────────────────────');
    console.log('Recommended Actions:');

    const displayCount = verbose ? report.actions.length : Math.min(10, report.actions.length);

    for (let i = 0; i < displayCount; i++) {
      const a = report.actions[i];
      const icon = a.automaticApplied ? '✓' : '○';
      const actionDisplay = a.action.toUpperCase().padEnd(8);

      console.log(`\n${icon} [${actionDisplay}] ${a.selector.substring(0, 40)}`);
      console.log(`  Reason: ${a.reason}`);

      if (a.suggestion) {
        console.log(`  Suggestion: ${a.suggestion.substring(0, 50)}`);
      }

      if (a.automaticApplied) {
        console.log(`  Status: Auto-applied`);
      }
    }

    if (!verbose && report.actions.length > 10) {
      console.log(`\n... and ${report.actions.length - 10} more (use --verbose)`);
    }
  }

  // Summary
  console.log('\n───────────────────────────────────────────────────────────────');
  console.log('Summary:');
  console.log(`  Total selectors:   ${report.summary.totalSelectors}`);
  console.log(`  At-risk:           ${report.summary.atRisk}`);
  console.log(`  Auto-applied:      ${report.summary.autoApplied}`);
  console.log(`  Optimizations:     ${report.summary.optimizations}`);
  console.log(`  Retirements:       ${report.summary.retirements}`);
  console.log(`  Monitored:         ${report.summary.monitored}`);

  // Save report
  fs.writeFileSync(PIPELINE_REPORT_FILE, JSON.stringify(report, null, 2));
  console.log(`\nReport saved to ${PIPELINE_REPORT_FILE}`);

  // CI mode
  if (ciMode) {
    if (report.exitCode !== 0) {
      console.log('\n✗ AUTO-REPAIR PIPELINE: FAILED');
      process.exit(report.exitCode);
    }
  }

  console.log('\n✓ AUTO-REPAIR PIPELINE: COMPLETE');
}

// Guard CLI entry point
if (require.main === module) {
  main();
}

// Export for use in other modules
export { runPipeline, PipelineReport, PipelineAction };
